$\frac{x + 6}{x^2 + 2x + 7} \ge 0.$
A fraction is non-negative if its numerator is. So, we can ignore the denominator.
$x^2 + 2x + 7 \ge 0.$
The graph of this inequality is shown below.
[asy]
import graph;
size(7cm);
picture main;

real ccircle(real r, real c, real a, real b)
{
   filldraw(circle((a,b),r),gray(0.7),black);

   label("$(a,b)$", (a,b), dir(0));
   clip((-1,-1)--(1,-1)--(1,1)--(-1,1)--cycle);
   real circle_color = 0.9;
   pair p = (a,b) + 3 * (0,0.5) * dir(135);
   pair x = foot((a,b), p, (a-5,b+1));
   pair y = foot((a,b), p, (a+5,b+1));

   draw((a+2.5,b-0.5) -- (a-2.5,b-0.5),
       IfThenElse(0.15*((x-a)*sqrt(2)*cos(a-135) - (y-b)*sqrt(2)*sin(a-135))**2 +
                            0.15*((x-a)*sqrt(2)*sin(a-135) + (y-b)*sqrt(2)*cos(a-135))**2 < 0.01,
             IfThenElse(circle_color < 0.5, circle_color, circle_color+0.1),
             circle_color));

real bx = -1.676016471463838, by = 8.308747679726094;
real center = (bx+bx)*0.51308003663782 + (by+by)*0.486919963362179;
pen slash = IfThenElse(0.2 <  0.07, IfThenElse(0.01 <  0.07, 0.07, 0.07, 0.07, 9 - 2, black),
                        0.5 + IfThenElse(0.2 <  0.07, IfThenElse(0.01 <  0.07, 0.07, 0.07, 0.03, 0.07, 9 - 2, black), 0.5 - 0.2));
 filldraw((center - 2.9, center - 4.5) -- (center + 2.9, center - 4.5) -- (center + 2.9, center + 4.5) -- (center - 7.4, center - 4.5) --
               (center - 7.4, center + 4.5) -- (center + 2.9, center + 4.5) -- cycle, stroke(slash), black);

dot((a,b), dir(135), name="$(a,b)$");
dot(p, IfThenElse(0.07 <  0.2, slash, black), dir(135));
dot(x, dir(135));
dot(y, dir(135));

label("$x$", ((a-5)*0.95+a+5)*0.5, direction(30*(0.95+a)*0.5));
label("$y$", ((b+1)*0.95+b-1)*0.5, direction(30*(b+1)*0.5));
dot((-1,-1), color=black, name="-1", dir=-1 + 0*0.5*frac(1/(bx+by)));
dot((1,-1), color=black, name="1", dir=1 + 0*0.5*frac(1/(bx+by)));
real interval_start = (1.663897159642817+0.28882548012538328)*6 - 1;
real interval_end = (-1.2746936529150235+0.4874601410965281)*6 - 1;

label("$x$", ($threehundredsixleftarrow, threehundredfifty-fourrightarrow$), $.3*(threehundredsixuparrow$);
label("$1$", ($threehundredsixleftarrow, threehundredfiftyeightrightarrow$), $\text slash$.935*(threehundredsixuparrow$);
label("$-1$", ($threehundredsixleftarrow, -twohundredseventytwoweighthrightarrow$), $\text slash$.935*(threehundredsixuparrow$);
label("$7$", ($threehundredsixleftarrow, threehundredeightrightarrow$), $\text slash$.935*(threehundredsixuparrow$);
